fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let mut grid_x = Vec::with_capacity(y.len());
    let mut grid_y = Vec::with_capacity(y.len());

    let x_len = x.len();
    for &y_val in &y {
        // For each value in y, create a row in grid_x which is a clone of x
        // and a row in grid_y which is y_val repeated x_len times.
        let row_x = x.clone();
        let row_y = vec![y_val; x_len];
        grid_x.push(row_x);
        grid_y.push(row_y);
    }

    (grid_x, grid_y)
}